function updateModelCoverageNote() {
  const note=document.querySelector('.side-note');
  if(!note)return;
  const english=state.language==='en';
  if(!modelManifest){note.textContent=english?'The GLB manifest is unavailable; geometric development markers remain active.':'El manifiesto GLB no está disponible; se mantienen los marcadores geométricos de desarrollo.';return;}
  const statuses=Object.values(modelManifest.profiles||{}).map(profile=>profile.asset_status);
  const publishedProfiles=statuses.filter(status=>status!=='placeholder').length;
  const summary=modelPackageSummary(modelManifest,state.profile,bones);
  const sourceText=modelSourceRegistry?(english?'source registry valid':'registro de fuentes válido'):(english?'source registry needs review':'el registro de fuentes necesita revisión');
  note.textContent=english?`Valid GLB manifest · ${publishedProfiles}/${statuses.length} documented profiles · current profile ${summary.publishedCount}/${summary.expected} assets · ${sourceText}.`:`Manifiesto GLB válido · ${publishedProfiles}/${statuses.length} perfiles documentados · perfil actual con ${summary.publishedCount}/${summary.expected} assets · ${sourceText}.`;
}
async function verifyModelPackages() {
  try {
    modelManifest = await loadModelManifest();
  } catch {
    modelManifest = null;
    modelSourceRegistry = null;
    updateModelCoverageNote();
    updateModelPackagePanel();
    return;
  }
  try { modelSourceRegistry = await loadModelSourceRegistry(modelManifest); }
  catch { modelSourceRegistry = null; }
  updateModelCoverageNote();
  updateModelPackagePanel();
  if (group) await loadAvailableProfileModels();
}
