document.querySelector('#calibrate-landmarks')?.addEventListener('click', async () => {
  if (state.locked[state.selected]) { document.querySelector('#calibration-status').textContent = 'Registro bloqueado'; return; }
  if (state.landmarkModelRefs?.[state.selected]?.needsReview) { document.querySelector('#calibration-status').textContent = 'Confirma primero la revisión del modelo actual.'; return; }
  const points=state.landmarks[state.selected]||[], reference=Number(document.querySelector('#landmark-reference-mm').value);
  if (points.length<2 || !Number.isFinite(reference) || reference<=0) { document.querySelector('#calibration-status').textContent='Necesitas dos landmarks y una distancia real positiva en mm.'; return; }
  const localDistance=Math.hypot(points[1].x-points[0].x,points[1].y-points[0].y,points[1].z-points[0].z);
  if (!Number.isFinite(localDistance)||localDistance<=0) { document.querySelector('#calibration-status').textContent='Los dos landmarks no pueden ocupar el mismo punto.'; return; }
  const previous=structuredClone(state.calibrations[state.selected]||null);
  commitInventoryEdit('landmark_calibration',()=>{ state.calibrations[state.selected]={referenceMm:reference,localDistance,updatedAt:new Date().toISOString()}; });
  recordInventoryFieldChange(state.selected,'calibration',previous,state.calibrations[state.selected],'landmark_calibration');
  refreshLandmarkDistance(); document.querySelector('#calibration-status').textContent=`Escala guardada: ${(reference/localDistance).toFixed(3)} mm/unidad local.`; await saveLocal({notify:false});
});
