const paintRegionTargets = [['cervical','Columna cervical'],['thoracic','Columna torácica'],['lumbar','Columna lumbar'],['pelvis','Pelvis'],['upper_left','Extremidad superior izquierda'],['upper_right','Extremidad superior derecha'],['hand_left','Mano izquierda'],['hand_right','Mano derecha'],['lower_left','Extremidad inferior izquierda'],['lower_right','Extremidad inferior derecha'],['foot_left','Pie izquierdo'],['foot_right','Pie derecho']];
