document.querySelectorAll('[data-paint-tool]').forEach(button=>button.onclick=()=>{state.paintTool=button.dataset.paintTool;document.querySelectorAll('[data-paint-tool]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));const input=document.querySelector('#paint-alteration');if(input)input.hidden=!['taphonomy','pathology'].includes(state.paintTool);document.querySelector('#toast').textContent=`Herramienta: ${button.textContent}`;});
setTimeout(()=>{const regionTarget=document.querySelector('#region-target');if(!regionTarget)return;regionTarget.onchange=event=>{const region=event.target.value;if(!region)return;const side=document.querySelector('#paint-side-filter')?.value||'both';const matchesSide=bone=>side==='both'||(side==='left'&&bone.side==='Izquierda')||(side==='right'&&bone.side==='Derecha');const selected=bones.filter(bone=>matchesPaintRegion(bone,region)&&matchesSide(bone)&&!state.locked[bone.id]);if(!selected.length){event.target.value='';return;}const previous=snapshotInventory();state.history.push(previous);state.future=[];const alteration=String(document.querySelector('#paint-alteration')?.value||'').trim();selected.forEach(bone=>{const tool=state.paintTool||'status';if(tool==='status')state.status[bone.id]=state.activeStatus;else if(tool==='preservation')state.preservation[bone.id]=document.querySelector('#preservation').value;else if(tool==='percentage')state.completeness[bone.id]=Math.max(0,Math.min(100,Number(document.querySelector('#completeness').value)||0));else if(tool==='taphonomy'||tool==='pathology'){if(alteration){const target=tool==='taphonomy'?state.taphonomy:state.pathology;target[bone.id]=[...(target[bone.id]||[]),alteration].filter((value,index,array)=>array.indexOf(value)===index);}}else if(tool==='erase'){state.status[bone.id]='not_recorded';state.preservation[bone.id]='not_evaluated';state.completeness[bone.id]=100;delete state.taphonomy[bone.id];delete state.pathology[bone.id];delete state.taphonomyDetails[bone.id];delete state.pathologyDetails[bone.id];delete state.notes[bone.id];}});recordInventorySnapshotChanges(previous,snapshotInventory(),'mass_region');event.target.value='';updateInventory();updateInventoryProgress();saveLocal();document.querySelector('#toast').textContent=`${selected.length} elementos actualizados`;};},0);
